// Saturday media day (GDD §20.1): the owner answers three questions from the
// press. Every answer is written in the voice of one of the 25 natures; the
// monsters on the roster who share that nature hear themselves in it and play
// Sunday with a lift to their nature's strength. 250 questions, ten "about"
// each nature (its first answer is that nature's), so a roster built around
// swift monsters sees swift questions more often than not.
//
// `{opp}`, `{rival}`, `{star}`, `{record}`, `{club}` and `{week}` are filled in.
// A question may be tied to a situation: rival (rival game this week),
// hotseat (board confidence at the hot-seat line), playoff, streakW/streakL
// (three straight), injury (a starter is out). Situational questions jump the
// queue when their situation is live and are never asked otherwise.

const Q = (nature, q, a1, a2, a3, extra = {}) => ({ nature, q, a: [a1, a2, a3].map(([text, t, flags]) => ({ text, t, ...(flags || {}) })), ...extra });

export const QUESTIONS = Object.freeze([
  // ---------------------------------------------------------------- swift (speed)
  Q('swift', 'How do you see Sunday against {opp}?', ['We’re faster than them at every spot. We’ll make them chase.', 'swift'], ['They’re dangerous. We’ve prepared for everything.', 'focused'], ['We just want to go out and play our game.', 'balanced']),
  Q('swift', '{opp} has the slowest secondary in the league. Do you attack that?', ['Every snap. Speed is the one thing you can’t coach on a Saturday.', 'swift'], ['We’ll take what they give us. No forcing it.', 'patient'], ['We’ll test them early and adjust from there.', 'adaptive']),
  Q('swift', 'Your receivers were running past people all week in practice. Is that the plan?', ['If they can’t keep up, that’s not our problem.', 'swift'], ['Practice is practice. Sunday we take care of the ball first.', 'secure'], ['The plan is whatever the first quarter tells us.', 'cerebral']),
  Q('swift', 'Is this the fastest team you’ve ever coached?', ['Yes. And we’re going to play like it — tempo, tempo, tempo.', 'swift'], ['Fast is nice. Tough wins in December.', 'sturdy'], ['Fast and smart. One without the other gets you beat.', 'focused']),
  Q('swift', 'Will we see more no-huddle this week?', ['Count on it. Tired defenses make mistakes.', 'swift'], ['When the moment calls for it. We won’t rush for the sake of it.', 'patient'], ['We’ll run it until they prove they can stop it, then change.', 'adaptive']),
  Q('swift', 'Your kick returner nearly broke two last week. Green light?', ['Always. If he sees grass, he goes.', 'swift'], ['Green light inside the five only. Field position wins games.', 'disciplined'], ['He’s earned the right to make that read himself.', 'instinctive']),
  Q('swift', 'Does the track-meet style hold up in bad weather?', ['Speed doesn’t care about the forecast.', 'swift'], ['We’ve got a power package for exactly that day.', 'powerful'], ['We’ll keep the ball on the ground and keep it safe.', 'secure']),
  Q('swift', 'What was the first thing you looked for when you built this roster?', ['Speed. You can teach a lot of things; you can’t teach fast.', 'swift'], ['Hands. Drops kill drives.', 'surehanded'], ['Brains. I want monsters who know why, not just what.', 'cerebral']),
  Q('swift', '{opp}’s coach said your team "runs out of gas". Response?', ['Then they should try keeping up for four quarters.', 'swift'], ['We’ll let the fourth quarter answer that.', 'relentless'], ['I don’t respond to other coaches. We’ll play.', 'calm']),
  Q('swift', 'Any changes to the return game after last week?', ['We’re putting our fastest monster back there. Let’s see them cover it.', 'swift'], ['Ball security first. Fair catches are fine by me.', 'secure'], ['Same unit. One bad week doesn’t change the plan.', 'hardy']),

  // ---------------------------------------------------------------- explosive (first burst)
  Q('explosive', 'Your offense has the most 20-yard plays in the league. Luck or design?', ['Design. We want the big play on every snap, not the safe one.', 'explosive'], ['Design and patience. Big plays come when you’ve earned them.', 'patient'], ['Mostly our quarterback reading it right.', 'cerebral']),
  Q('explosive', 'How do you start fast against {opp}?', ['First drive, we swing. Score early and let them chase.', 'explosive'], ['We start by not turning it over. Boring wins first quarters.', 'secure'], ['We script the first eight plays and trust the script.', 'disciplined']),
  Q('explosive', 'Your defense made three plays behind the line last week. Sustainable?', ['Yes. We attack the snap. That doesn’t change.', 'explosive'], ['If we keep our lanes, the plays come. Discipline first.', 'disciplined'], ['We’ll keep sending pressure until someone makes us pay.', 'ferocious']),
  Q('explosive', 'Do you worry about your monsters wearing down late?', ['We’d rather burn hot for three quarters than smoulder for four.', 'explosive'], ['That’s why we go two deep everywhere.', 'hardy'], ['Conditioning. We’ll be fresh in the fourth.', 'relentless']),
  Q('explosive', '{star} had a 60-yard touchdown last week. How do you get more of that?', ['Give him the ball in space and get out of the way.', 'explosive', { star: true }], ['Keep feeding him — the long one comes from the short ones.', 'patient'], ['Move him around so they can’t find him.', 'elusive']),
  Q('explosive', 'Your first drives have been your best. Why?', ['Because we come out swinging. That’s who we are.', 'explosive'], ['Because we study tape. The first drive is the scouting report.', 'cerebral'], ['Because our monsters are fresh. The job is staying that way.', 'sturdy']),
  Q('explosive', 'Is there a trick play in the bag this week?', ['There’s always one. Maybe two.', 'explosive'], ['We win with execution, not tricks.', 'precise'], ['You never know with us.', 'slippery']),
  Q('explosive', 'How much of the game plan is built around the deep ball?', ['A lot. Three shots a quarter, minimum.', 'explosive'], ['Enough to keep them honest, no more.', 'balanced'], ['It depends on what their safeties show us.', 'adaptive']),
  Q('explosive', 'Any message for the fans before kickoff?', ['Get there early. The first quarter is going to be loud.', 'explosive'], ['Stay till the end. We finish.', 'relentless'], ['Enjoy it. We will.', 'calm']),
  Q('explosive', 'Your blitz rate is the highest in the league. Will that continue?', ['Why would we stop? Pressure wins.', 'explosive'], ['We’ll pick our spots. A smart quarterback punishes a blind blitz.', 'focused'], ['We’ll bring it until they block it.', 'aggressive']),

  // ---------------------------------------------------------------- elusive (evasion)
  Q('elusive', '{opp} tackles well. How do you deal with that?', ['You can’t tackle what you can’t touch. We’ll make them miss.', 'elusive'], ['Run right at them. Make the tacklers earn it.', 'powerful'], ['Short passes, quick decisions. Don’t give them time to line up a hit.', 'precise']),
  Q('elusive', 'Your running backs broke eleven tackles last week. Coaching or talent?', ['Both. We drill the cut every day; the instinct is theirs.', 'elusive'], ['Talent. My job is to get them the ball and not get in the way.', 'gifted'], ['The line. Nobody breaks tackles behind bad blocking.', 'protective']),
  Q('elusive', 'How do you keep your quarterback upright this week?', ['Move the pocket. A moving target is a hard target.', 'elusive'], ['Max protect and trust the line.', 'protective'], ['Get the ball out quick. Nobody can sack a throw.', 'precise']),
  Q('elusive', 'Will we see more misdirection on Sunday?', ['Plenty. If they want to fly to the ball, we’ll send them the wrong way.', 'elusive'], ['Some. The base plays still have to work first.', 'balanced'], ['We’ll see what their linebackers bite on and go from there.', 'adaptive']),
  Q('elusive', 'Your team avoids big hits more than most. Is that by design?', ['Yes. Healthy in week ten beats tough in week two.', 'elusive'], ['We don’t avoid anything. We just don’t seek them out.', 'calm'], ['Our monsters can take a hit. They just don’t have to.', 'sturdy']),
  Q('elusive', 'What makes {star} so hard to bring down?', ['Feet. He changes direction faster than anyone can react.', 'elusive', { star: true }], ['He sees the tackle coming before the tackler does.', 'instinctive'], ['Balance. Hit him and he just keeps going.', 'sturdy']),
  Q('elusive', '{opp}’s defense plays very aggressive. Does that worry you?', ['It excites me. Aggressive defenders overrun plays.', 'elusive'], ['We’ll match it. Physical game, fine.', 'aggressive'], ['No. Aggressive is just another word for predictable.', 'cerebral']),
  Q('elusive', 'How do you game-plan a pass rush like theirs?', ['Screens and draws. Let them run themselves out of the play.', 'elusive'], ['Chip them, double them, slow them down.', 'protective'], ['Quick game. Three steps and gone.', 'technical']),
  Q('elusive', 'Any thoughts on the officiating this season?', ['We’d rather not be touched at all. Solves the problem.', 'elusive'], ['We play clean and let the flags fall where they fall.', 'disciplined'], ['No comment. Really.', 'calm']),
  Q('elusive', 'What did you work on this week?', ['Open-field moves. Make one monster miss and it’s a different game.', 'elusive'], ['Details. Footwork, reads, assignments.', 'technical'], ['Hitting. We want to be the tougher team.', 'powerful']),

  // ---------------------------------------------------------------- powerful (strength)
  Q('powerful', 'What’s the identity of this offense?', ['Run the ball down their throat until they beg us to pass.', 'powerful'], ['Balance. Keep them guessing.', 'balanced'], ['Tempo and space. We’ll stretch them thin.', 'swift']),
  Q('powerful', '{opp} is small up front. Do you exploit that?', ['Absolutely. We’ll be in their backfield all day.', 'powerful'], ['We’ll test it, but their speed is the real problem.', 'cerebral'], ['We play the same way no matter who it is.', 'hardy']),
  Q('powerful', 'Short yardage has been a problem. Fixed?', ['Fixed. We put the biggest monsters on the field and go straight ahead.', 'powerful'], ['We’ll be sneakier. Nobody expects the pass on fourth and one.', 'slippery'], ['We’ll avoid third and short by winning first down.', 'focused']),
  Q('powerful', 'Is this a physical football team?', ['The most physical in the league, and we’ll prove it again Sunday.', 'powerful'], ['Physical when it needs to be. Smart always.', 'cerebral'], ['We finish every play. That’s our kind of physical.', 'relentless']),
  Q('powerful', 'How do you stop {opp}’s running game?', ['Win the line. Knock them backwards and the run dies.', 'powerful'], ['Gap discipline. Everybody in their lane.', 'disciplined'], ['Swarm. Eleven hats to the ball.', 'aggressive']),
  Q('powerful', 'Your goal-line package is almost all linemen. Why?', ['Because the goal line is a strength contest, and we win those.', 'powerful'], ['Because it’s worked. Why change it?', 'hardy'], ['Because it sets up the play-action nobody sees coming.', 'slippery']),
  Q('powerful', 'Any concerns about {opp}’s defensive line?', ['They’ll be concerned about ours by halftime.', 'powerful'], ['Respect. They earn every sack. We’ll chip and double.', 'protective'], ['We’ll move the pocket and keep them guessing.', 'elusive']),
  Q('powerful', 'What’s the message to the offensive line this week?', ['Move people. Nothing else matters.', 'powerful'], ['Protect the quarterback. Everything flows from that.', 'protective'], ['Communicate. The sack comes from the missed call, not the lost block.', 'focused']),
  Q('powerful', 'How did {star} get so strong?', ['Work. The weight room is his second home.', 'powerful', { star: true }], ['Born that way. Some things you don’t coach.', 'gifted'], ['He eats hits for breakfast. Always has.', 'sturdy']),
  Q('powerful', 'Pass or run on fourth and one?', ['Run. Behind the biggest monster I have.', 'powerful'], ['Whatever the look tells us. We don’t decide in advance.', 'adaptive'], ['Punt, unless the game says otherwise. Field position matters.', 'patient']),

  // ---------------------------------------------------------------- sturdy (durability)
  Q('sturdy', 'How’s the injury situation?', ['We’re healthy, and we built this team to stay that way.', 'sturdy'], ['Next monster up. Our depth is ready.', 'hardy'], ['We’re managing it carefully. No one plays hurt.', 'calm']),
  Q('sturdy', 'Your monsters played every snap last week. Fatigue a worry?', ['These monsters are built for it. Durable is the first thing we look for.', 'sturdy'], ['We’ll rotate more this week. Fresh legs in the fourth.', 'relentless'], ['A little. We’ll be smart about it.', 'focused']),
  Q('sturdy', 'How do you handle a team that hits as hard as {opp}?', ['Hit back. We don’t go down easy and we don’t stay down.', 'sturdy'], ['Don’t let them land it. Quick feet, quick ball.', 'elusive'], ['Hit first. Set the tone on the opening drive.', 'aggressive']),
  Q('sturdy', 'Your team has the fewest fumbles in the league. Secret?', ['Two hands on the ball and monsters who don’t get knocked off their feet.', 'sturdy'], ['We drill ball security every single day.', 'secure'], ['Awareness. Know where the hit is coming from.', 'instinctive']),
  Q('sturdy', 'Is {star} playing through something?', ['He’s fine. That monster could play through a wall.', 'sturdy', { star: true }], ['We’ll make that call on Sunday morning, not today.', 'patient'], ['He’s healthy. Next question.', 'calm']),
  Q('sturdy', 'What do you want from your defense this week?', ['Absorb the first punch and keep standing. They’ll wear out before we do.', 'sturdy'], ['Takeaways. Turn the game in one play.', 'instinctive'], ['Stop the run and make them one-dimensional.', 'disciplined']),
  Q('sturdy', 'Long season. How do you keep the roster fresh?', ['Recruit durable monsters and train smart. We don’t break.', 'sturdy'], ['Rotation. Everybody plays, everybody rests.', 'hardy'], ['Mind the fatigue numbers. The data decides who sits.', 'cerebral']),
  Q('sturdy', 'Your tailback takes a lot of hits. Concerned?', ['He gives more than he takes. Watch the tacklers walk off slower.', 'sturdy'], ['We’ll spread the carries. He doesn’t need thirty.', 'patient'], ['He knows how to fall. That’s half of it.', 'technical']),
  Q('sturdy', 'How do you respond to a bruising loss like last week’s?', ['Get up. We always do.', 'sturdy'], ['Watch the tape, fix the three plays that mattered, move on.', 'cerebral'], ['Same routine. Nothing changes because of one Sunday.', 'hardy']),
  Q('sturdy', 'Any changes on the offensive line?', ['No. Those five have been standing up to everything. They’ll keep standing.', 'sturdy'], ['One tweak. We want a better blocker on the edge.', 'protective'], ['We’ll see how they handle {opp}’s front first.', 'adaptive']),

  // ---------------------------------------------------------------- relentless (late effort)
  Q('relentless', 'Your team has outscored opponents in the fourth quarter all season. Why?', ['Because we don’t stop. Ever. The fourth is where we live.', 'relentless'], ['Conditioning and depth. Fresh legs late.', 'hardy'], ['Because we save a few things for when it matters.', 'cerebral']),
  Q('relentless', 'What’s the message in the locker room this week?', ['Finish. Every play, every drive, every game.', 'relentless'], ['Keep stacking good days. Nothing changes.', 'hardy'], ['Trust the plan. Results follow.', 'focused']),
  Q('relentless', 'Your pass rush gets home late in games. Design?', ['Effort. Our rushers take forty snaps to wear a tackle down, then they eat.', 'relentless'], ['Stunts and games. We save the good ones.', 'technical'], ['Fresh bodies. We rotate four deep.', 'hardy']),
  Q('relentless', 'How do you keep the effort up when you’re down two scores?', ['We don’t know how to do anything else. Keep hitting.', 'relentless'], ['Stay calm, run the offense. Panic loses games faster than deficits.', 'calm'], ['Change something. Doing the same thing harder isn’t a plan.', 'adaptive']),
  Q('relentless', 'Your team practices longer than anyone. Does that pay off?', ['Every fourth quarter.', 'relentless'], ['It pays off if the reps are the right reps. Quality first.', 'precise'], ['We’ll find out in December.', 'patient']),
  Q('relentless', 'What makes {star} special?', ['Motor. He plays the last snap like the first.', 'relentless', { star: true }], ['Gifts. He does things nobody else on the field can.', 'gifted'], ['He never makes the same mistake twice.', 'focused']),
  Q('relentless', 'Is there such a thing as too much effort?', ['No. Effort has never lost us a game.', 'relentless'], ['Yes. Overrunning the play is effort in the wrong direction.', 'disciplined'], ['Effort without a plan, sure. We have a plan.', 'cerebral']),
  Q('relentless', 'How do you close out games?', ['Keep attacking. Playing not to lose is how you lose.', 'relentless'], ['Run the ball, run the clock, no risks.', 'secure'], ['Kick field goals and let the defense finish.', 'disciplined']),
  Q('relentless', 'Your defense allowed a long drive late last week. What happened?', ['We got tired and we stopped chasing. That won’t happen twice.', 'relentless'], ['A missed assignment. One. We’ve fixed it.', 'focused'], ['They made plays. Credit to them. Next.', 'calm']),
  Q('relentless', 'Do you believe in momentum?', ['I believe in the team that refuses to quit. Call it what you like.', 'relentless'], ['I believe in the next play.', 'calm'], ['I believe in whoever lines up right. Momentum is a story we tell after.', 'cerebral']),

  // ---------------------------------------------------------------- precise (accuracy)
  Q('precise', 'Your quarterback hasn’t thrown an interception in three weeks. Secret?', ['Decisions. He throws it where only we can catch it, or he throws it away.', 'precise'], ['Protection. A clean pocket makes anyone look smart.', 'protective'], ['He knows what the defense is doing before the snap.', 'cerebral']),
  Q('precise', 'Fans want more deep shots. Will they get them?', ['When the window is there. We don’t throw hope.', 'precise'], ['Yes. Fortune favours the bold.', 'explosive'], ['A few. Enough to keep them honest.', 'balanced']),
  Q('precise', 'Your kicker is perfect this season. Pressure building?', ['Not for him. Same routine, same swing, every time.', 'precise'], ['He doesn’t feel pressure. Ice in his veins.', 'calm'], ['Every kick is its own kick. He knows that.', 'focused']),
  Q('precise', 'What did you work on in practice this week?', ['Details. Footwork, reads, assignments. Precision wins.', 'precise'], ['Hitting. We want to be the tougher team.', 'powerful'], ['Conditioning. We’ll be fresh in the fourth.', 'relentless']),
  Q('precise', 'How do you attack {opp}’s coverage?', ['Timing. Ball out before the break, in the window, every time.', 'precise'], ['Speed. Run by them.', 'swift'], ['Patience. Take the checkdown until they come up, then go over the top.', 'patient']),
  Q('precise', 'Your team has the fewest penalties in the league. Why?', ['We practice the details until the details are habits.', 'precise'], ['Discipline. We don’t beat ourselves.', 'disciplined'], ['Smart monsters. They know where the line is.', 'cerebral']),
  Q('precise', 'How much freedom does your quarterback have at the line?', ['Plenty, because he earns it with accurate reads and accurate throws.', 'precise'], ['Full freedom. He sees things I don’t.', 'instinctive'], ['Some. The system is the system.', 'disciplined']),
  Q('precise', 'What makes {star} so efficient?', ['He never wastes a movement. Every step means something.', 'precise', { star: true }], ['Hands. He catches everything near him.', 'surehanded'], ['Preparation. He knows the opponent better than they do.', 'cerebral']),
  Q('precise', 'Any changes to the passing game after last week?', ['Tighter. Shorter routes, sharper timing. The yards will come.', 'precise'], ['Bigger. We were too conservative.', 'explosive'], ['No. One week isn’t a trend.', 'hardy']),
  Q('precise', 'Do you call plays by feel or by chart?', ['Chart. Feelings are how you get beat on third and four.', 'precise'], ['Feel. The chart doesn’t see the safety cheating.', 'instinctive'], ['Chart until the fourth quarter. Then feel.', 'adaptive']),

  // ---------------------------------------------------------------- surehanded (catching)
  Q('surehanded', 'Your receivers haven’t dropped a pass in three weeks. What changed?', ['We catch five hundred balls a day. Hands are a habit.', 'surehanded'], ['Better throws. Easier to catch a ball that’s on time.', 'precise'], ['Focus. Look it in, then run.', 'focused']),
  Q('surehanded', 'How do you win a game in the rain?', ['Catch the ball. Whoever holds on wins.', 'surehanded'], ['Run it. Keep it simple.', 'powerful'], ['Field position and patience. Let them make the mistake.', 'patient']),
  Q('surehanded', 'Will {star} see more targets this week?', ['Yes. He catches everything, so we throw him everything.', 'surehanded', { star: true }], ['He’ll get his. So will four other monsters.', 'balanced'], ['Depends on the coverage. We go where they aren’t.', 'adaptive']),
  Q('surehanded', 'Your tight end is turning into a real weapon. Surprised?', ['No. Best hands on the team. We just finally used them.', 'surehanded'], ['A little. He blocks so well we forgot he could catch.', 'protective'], ['He’s a mismatch. We knew it; now the league does.', 'cerebral']),
  Q('surehanded', 'How do you stop a secondary that jumps routes?', ['Strong hands. Win the contested catch and they stop jumping.', 'surehanded'], ['Double moves. Make them pay for guessing.', 'slippery'], ['Throw it where they aren’t. Simple.', 'precise']),
  Q('surehanded', 'Third down has been a struggle. Fix?', ['Catch the ball on third down. We had four drops. That’s the whole fix.', 'surehanded'], ['Stay out of third and long. Win first down.', 'focused'], ['Better protection. Our quarterback never had time.', 'protective']),
  Q('surehanded', 'Your defense leads the league in interceptions. Why?', ['Defensive backs with receiver hands. When the ball’s there, they catch it.', 'surehanded'], ['Pressure. Hurried throws find us.', 'ferocious'], ['Film. We know where the ball is going.', 'cerebral']),
  Q('surehanded', 'What does the punt returner need to do this week?', ['Catch it. Every time. Field the ball and we’re happy.', 'surehanded'], ['Make one monster miss and go.', 'elusive'], ['Fair catch unless it’s obvious. Possession first.', 'secure']),
  Q('surehanded', 'What did you look for in this year’s rookies?', ['Hands. Everything else we can teach.', 'surehanded'], ['Speed. You can’t teach fast.', 'swift'], ['Character. Monsters who want to be coached.', 'hardy']),
  Q('surehanded', 'Any superstitions before a game?', ['Every receiver catches fifty balls before warmups. Not a superstition — a rule.', 'surehanded'], ['Same breakfast, same seat on the bus. Don’t judge.', 'hardy'], ['None. Preparation is my superstition.', 'cerebral']),

  // ---------------------------------------------------------------- technical (crisp execution)
  Q('technical', 'What separates your receivers from the rest of the league?', ['Routes. Every cut is at the depth it should be, every time.', 'technical'], ['Speed. Separation is simple when you’re faster.', 'swift'], ['Hands. They catch what others drop.', 'surehanded']),
  Q('technical', 'Your pass protection was flawless last week. How?', ['Technique. Hands inside, feet set, eyes up. Every rep.', 'technical'], ['Effort. Five monsters who refuse to lose.', 'relentless'], ['Communication. The line called every stunt before it came.', 'focused']),
  Q('technical', 'How do you coach a young quarterback?', ['Mechanics first. Footwork fixes more problems than film does.', 'technical'], ['Protect him. Confidence comes from a clean jersey.', 'protective'], ['Let him play. Instincts can’t be taught from a chair.', 'instinctive']),
  Q('technical', 'What did you learn from the loss to {opp} earlier?', ['We lost on technique. Pad level, hand placement, small things. All fixed.', 'technical'], ['That we needed to be tougher. We are now.', 'powerful'], ['That they’re good. Nothing more dramatic than that.', 'calm']),
  Q('technical', 'Your defensive line seems to win with moves, not muscle. Fair?', ['Fair. A good swim move beats a bad bull rush every time.', 'technical'], ['Half right. The muscle is there when we need it.', 'powerful'], ['They win with whatever works that snap.', 'adaptive']),
  Q('technical', 'How do you prepare the special teams?', ['Every player knows their steps. Kick coverage is a choreography.', 'technical'], ['Effort. We send the hungriest monsters down the field.', 'relentless'], ['Simplicity. Fewer calls, fewer mistakes.', 'disciplined']),
  Q('technical', 'Does {star} have a weakness?', ['Not a technical one. His footwork is a textbook.', 'technical', { star: true }], ['Everyone does. We hide his and show his strengths.', 'cerebral'], ['If he does, {opp} hasn’t found it.', 'calm']),
  Q('technical', 'What’s the key to a clean tackle?', ['Head across, wrap, drive. We teach it the same way every day.', 'technical'], ['Want to. Technique follows desire.', 'aggressive'], ['Angle. Get the angle right and the tackle makes itself.', 'instinctive']),
  Q('technical', 'How do you develop monsters nobody else wanted?', ['Fundamentals. Most of them were never taught the small things.', 'technical'], ['Patience. Give them a year and watch.', 'patient'], ['Put them where their one gift matters most.', 'gifted']),
  Q('technical', 'Your run blocking looks different this year. What changed?', ['Footwork. We rebuilt the first two steps of every block.', 'technical'], ['Attitude. We decided to move people.', 'powerful'], ['Personnel. We found linemen who stay on blocks.', 'protective']),

  // ---------------------------------------------------------------- cerebral (reads)
  Q('cerebral', 'How much tape did you watch on {opp} this week?', ['All of it. Twice. They have a tell on every third down and we found it.', 'cerebral'], ['Enough. At some point you have to trust your monsters.', 'calm'], ['Plenty, and we’ll still adjust at halftime.', 'adaptive']),
  Q('cerebral', 'Your defense seems to know the play before the snap. How?', ['Study. Formation, split, stance — it’s all there if you look.', 'cerebral'], ['Instinct. Some monsters just feel it.', 'instinctive'], ['Discipline. Nobody guesses, so nobody is out of place.', 'disciplined']),
  Q('cerebral', 'Do you believe in analytics?', ['I believe in information. Every decision we make is a numbers decision.', 'cerebral'], ['I believe in the monsters I can see. Numbers after.', 'instinctive'], ['A bit of both. Numbers tell you what; eyes tell you why.', 'balanced']),
  Q('cerebral', 'Why does {star} always seem to be in the right place?', ['Because he studies more than anyone in this building. Including me.', 'cerebral', { star: true }], ['Because he reacts faster than the ball.', 'instinctive'], ['Because he never leaves his assignment.', 'disciplined']),
  Q('cerebral', 'Fourth and short at midfield. Go?', ['Depends on the numbers. The chart says yes more often than you’d think.', 'cerebral'], ['Go. Always. Fortune favours the bold.', 'aggressive'], ['Punt. Make them drive the field.', 'patient']),
  Q('cerebral', 'What do you tell a monster who keeps making the same mistake?', ['Show him why. Nobody fixes what they don’t understand.', 'cerebral'], ['Show him once, then bench him. Reps are earned.', 'disciplined'], ['Stay with him. Mistakes are tuition.', 'patient']),
  Q('cerebral', 'Your halftime adjustments are becoming famous. What goes on in there?', ['We ask one question: what did they show us that the tape didn’t? Then we answer it.', 'cerebral'], ['We change what isn’t working. Not complicated.', 'adaptive'], ['Mostly we breathe. The plan was right; execute it.', 'calm']),
  Q('cerebral', 'How do you prepare for a coach you’ve never faced?', ['Read everything. Tendencies travel with the coach, not the roster.', 'cerebral'], ['We prepare for ourselves. Our game, our way.', 'hardy'], ['Expect surprises and stay flexible.', 'adaptive']),
  Q('cerebral', 'What is the most underrated attribute in football?', ['Awareness. Fast and strong is wasted on a monster who doesn’t know where to be.', 'cerebral'], ['Durability. The best ability is availability.', 'sturdy'], ['Hands. Drives die on drops.', 'surehanded']),
  Q('cerebral', 'Did {opp}’s last game tell you anything?', ['It told me three things, and we’ll show you one of them in the first quarter.', 'cerebral'], ['It told me they’re tough. That’s all I needed.', 'sturdy'], ['It told me nothing I didn’t know. We play our game.', 'hardy']),

  // ---------------------------------------------------------------- instinctive (reaction)
  Q('instinctive', 'Your defense leads the league in takeaways. Scheme or instinct?', ['Instinct. We recruit monsters who feel the ball coming and let them go get it.', 'instinctive'], ['Scheme. We put them in position; they finish.', 'cerebral'], ['Pressure. Hurried throws find us.', 'ferocious']),
  Q('instinctive', 'Your quarterback improvises a lot. Does that worry you?', ['No. His first instinct is usually the right one. I stay out of the way.', 'instinctive'], ['Sometimes. We want him within the structure first.', 'disciplined'], ['It would if he turned it over. He doesn’t.', 'secure']),
  Q('instinctive', 'How do you teach a monster to read a play?', ['You don’t teach it. You find monsters who already see it and give them reps.', 'instinctive'], ['Film, film, film. Reads are learned.', 'cerebral'], ['Reps. Thousands of them. The body learns before the mind does.', 'technical']),
  Q('instinctive', 'Why does {star} always find the ball?', ['Instinct. He breaks before the receiver does. You can’t coach that.', 'instinctive', { star: true }], ['Film. He knows the route before the snap.', 'cerebral'], ['Speed. He gets there because he’s faster.', 'swift']),
  Q('instinctive', 'Do you script your opening drive?', ['Loosely. The first play tells us more than any script could.', 'instinctive'], ['Every play. Fifteen of them.', 'disciplined'], ['First five, then we feel it out.', 'adaptive']),
  Q('instinctive', 'Your safeties freelance more than most. Risky?', ['They see things. When a monster sees it, you let him go.', 'instinctive'], ['A bit. We rein it in when it costs us.', 'disciplined'], ['Not with the way they tackle. Even a wrong guess ends in a hit.', 'aggressive']),
  Q('instinctive', 'How did you know to go for it on fourth down last week?', ['I didn’t know. I felt it. So did the sideline.', 'instinctive'], ['The chart said go. I just followed it.', 'cerebral'], ['The look they gave us. It was there.', 'adaptive']),
  Q('instinctive', 'What makes a great returner?', ['Vision. The hole is open for a tenth of a second and he’s already in it.', 'instinctive'], ['Speed. Everything else is secondary.', 'swift'], ['Courage. Catch it clean with eleven monsters coming.', 'surehanded']),
  Q('instinctive', 'How do you decide who starts at linebacker?', ['Who finds the ball in practice. The stats follow the instinct.', 'instinctive'], ['Who tackles. Everything else is noise.', 'aggressive'], ['Who knows the calls. A smart linebacker fixes a dumb defense.', 'cerebral']),
  Q('instinctive', 'Your team recovers a lot of loose balls. Luck?', ['Luck is where the ball lands. Being there isn’t.', 'instinctive'], ['Effort. We run to the ball on every play.', 'relentless'], ['Training. We practice the scramble drill weekly.', 'technical']),

  // ---------------------------------------------------------------- focused (fewer errors)
  Q('focused', 'Your team has the fewest missed assignments in the league. How?', ['Every monster knows his job and only his job. Focus is the whole game.', 'focused'], ['Simple scheme. Fewer calls, fewer mistakes.', 'disciplined'], ['Smart monsters. We recruit for it.', 'cerebral']),
  Q('focused', 'Does a big game change your preparation?', ['No. Same week, same meetings, same walk-through. The noise is outside.', 'focused'], ['A little more edge in practice. The monsters feel it.', 'aggressive'], ['It changes nothing except how loud the stadium is.', 'calm']),
  Q('focused', 'How do you keep young monsters from getting distracted?', ['One job per play. Do it. The rest is my problem.', 'focused'], ['Veterans. The old monsters police the young ones.', 'hardy'], ['Reps until it’s boring. Boring is good.', 'technical']),
  Q('focused', 'Your kicker missed a short one last week. Concerned?', ['No. One lapse. His routine is back and that’s all it takes.', 'focused'], ['He’ll kick through it. Short memory.', 'calm'], ['We’ll give him more work in practice and see.', 'patient']),
  Q('focused', 'What’s the key to beating {opp}?', ['Doing our jobs on every snap. They feed on mistakes. We won’t make any.', 'focused'], ['Outhit them. It’s that kind of game.', 'powerful'], ['Make them one-dimensional. Then take that dimension away.', 'cerebral']),
  Q('focused', 'How does {star} stay so consistent?', ['He locks in. Nothing outside the lines reaches him.', 'focused', { star: true }], ['Routine. Same week, every week.', 'hardy'], ['Talent. Consistency is easy when you’re that good.', 'gifted']),
  Q('focused', 'The crowd will be hostile. Does that matter?', ['Only if we listen. We won’t.', 'focused'], ['We like it loud. Makes the silence after a touchdown better.', 'aggressive'], ['It matters for the snap count. We’ve practised for it.', 'technical']),
  Q('focused', 'Any changes after the penalties last week?', ['We addressed it. Focus on the ball, not the whistle.', 'focused'], ['We play hard. Some flags come with that.', 'aggressive'], ['Yes. Clean football or sit.', 'disciplined']),
  Q('focused', 'How do you prepare the defense for a quarterback who scrambles?', ['Eyes. Everybody keeps their eyes where they belong and the scramble goes nowhere.', 'focused'], ['Spy him. One monster, all day.', 'disciplined'], ['Hit him. Scramblers stop scrambling when it hurts.', 'ferocious']),
  Q('focused', 'What worries you most about Sunday?', ['Nothing outside our control. We handle our side; the rest takes care of itself.', 'focused'], ['Their front. We need to be ready for a fight.', 'protective'], ['Nothing. Worry is wasted energy.', 'calm']),

  // ---------------------------------------------------------------- aggressive (big hits)
  Q('aggressive', 'How do you set the tone against {opp}?', ['First snap, somebody gets hit hard. Then they know.', 'aggressive'], ['First drive, we score. Then they know.', 'explosive'], ['First quarter, no mistakes. Then they know.', 'focused']),
  Q('aggressive', 'Your defense has a reputation for big hits. Fair?', ['Earned. We play to the whistle and we play through the ball carrier.', 'aggressive'], ['We play hard and clean. The hits come from the effort.', 'relentless'], ['We’d rather be known for takeaways. The hits are a bonus.', 'instinctive']),
  Q('aggressive', 'Do you ever tell your monsters to dial it back?', ['Never. I tell them to aim better.', 'aggressive'], ['When it costs us flags. Discipline wins close games.', 'disciplined'], ['When they’re tired. Smart aggression, not blind.', 'cerebral']),
  Q('aggressive', 'Fourth and goal from the one. Field goal or go?', ['Go. We didn’t drive ninety-nine yards to kick.', 'aggressive'], ['Points. Three is better than nothing.', 'patient'], ['Depends on the score and the clock. The chart knows.', 'cerebral']),
  Q('aggressive', 'What do you want from your linebackers this week?', ['Violence. Legal, controlled, every snap.', 'aggressive'], ['Gaps. Fill them and the run dies.', 'disciplined'], ['Reads. Know where the ball is going before it goes.', 'instinctive']),
  Q('aggressive', '{opp}’s quarterback is young. Does that change the plan?', ['We’re going to introduce ourselves early and often.', 'aggressive'], ['We’ll confuse him. Young quarterbacks hate disguise.', 'cerebral'], ['No. We play our defense regardless.', 'hardy']),
  Q('aggressive', 'Your blitz rate is up. Why?', ['Because waiting is losing. We go get the quarterback.', 'aggressive'], ['Because the front four weren’t getting home. We adjusted.', 'adaptive'], ['Because {opp}’s line can’t handle it. Specific to this week.', 'cerebral']),
  Q('aggressive', 'Is {star} too physical for his own good?', ['No such thing. He’s the reason receivers hear footsteps.', 'aggressive', { star: true }], ['He walks the line. We keep him on the right side of it.', 'disciplined'], ['He’s physical and smart. Rare combination.', 'cerebral']),
  Q('aggressive', 'How do you respond to {opp}’s trash talk this week?', ['On the field. Loudly.', 'aggressive'], ['We don’t. Talk is free; wins aren’t.', 'calm'], ['We write it down and read it at halftime.', 'relentless']),
  Q('aggressive', 'Will your defense play as physical as last week?', ['More. Last week was the warm-up.', 'aggressive'], ['Same. That’s our standard.', 'hardy'], ['Physical where it counts. Smart everywhere else.', 'focused']),

  // ---------------------------------------------------------------- disciplined (assignment)
  Q('disciplined', 'Your team never seems to be out of position. Why?', ['Assignment football. Everyone where they belong, every snap, no freelancing.', 'disciplined'], ['Smart monsters. They understand the why.', 'cerebral'], ['Reps. We practise alignment until it’s automatic.', 'technical']),
  Q('disciplined', '{opp} runs a lot of misdirection. How do you handle it?', ['Eyes on your key, stay home, trust the monster next to you.', 'disciplined'], ['Speed. Be wrong fast and recover faster.', 'swift'], ['Read it. The misdirection has a tell.', 'cerebral']),
  Q('disciplined', 'How do you avoid penalties on the road?', ['Snap count, pad level, hands in. The basics. We don’t beat ourselves.', 'disciplined'], ['Focus. Block out the crowd.', 'focused'], ['Play hard. Flags happen. We accept a few.', 'aggressive']),
  Q('disciplined', 'Your defense bends but rarely breaks. Philosophy?', ['Keep everything in front, tackle, make them earn ten plays. Nobody is that patient.', 'disciplined'], ['Attack. We’d rather break than bend, frankly.', 'aggressive'], ['Take the ball away. Every drive is a chance.', 'instinctive']),
  Q('disciplined', 'Will you let {star} freelance against this offense?', ['No. His discipline is why he makes plays. He stays in the structure.', 'disciplined', { star: true }], ['Yes. He sees it; he goes.', 'instinctive'], ['A little. We give him two calls a half.', 'balanced']),
  Q('disciplined', 'What’s the rule on fourth down in your own territory?', ['Punt. Every time. We play the field-position game and win it.', 'disciplined'], ['Depends on the game. We’ve gone for it before.', 'aggressive'], ['Numbers. We follow the chart.', 'cerebral']),
  Q('disciplined', 'How do you keep the offense from turning the ball over?', ['Rules. Two hands in traffic, throw it away on the third read. Non-negotiable.', 'disciplined'], ['Ball security drills. Every day.', 'secure'], ['Smart decisions. Our quarterback knows when to say no.', 'precise']),
  Q('disciplined', 'Your team is young. How do you keep it steady?', ['Structure. Same schedule, same standards, no exceptions.', 'disciplined'], ['Veterans. They set the tone.', 'hardy'], ['Patience. Young teams learn by playing.', 'patient']),
  Q('disciplined', 'What do you tell your corners about {opp}’s receivers?', ['Stay in your coverage. They want you to guess. Don’t.', 'disciplined'], ['Be physical at the line. Make them earn every release.', 'aggressive'], ['Read the quarterback’s eyes. He tells you everything.', 'instinctive']),
  Q('disciplined', 'How did you clean up the mistakes from last week?', ['We went back to the rules. Every error was a rule broken.', 'disciplined'], ['We showed them the tape. Mistakes fix themselves when you see them.', 'cerebral'], ['More reps. Mistakes are a practice problem.', 'technical']),

  // ---------------------------------------------------------------- ferocious (pass rush)
  Q('ferocious', 'How do you plan to handle {opp}’s quarterback?', ['Hit him. Early, often, legally. Everything gets easier after that.', 'ferocious'], ['Confuse him. Disguise everything.', 'cerebral'], ['Contain him. No big plays, make him patient.', 'disciplined']),
  Q('ferocious', 'Your defensive line had five sacks last week. More coming?', ['More. They smell blood now.', 'ferocious'], ['If the coverage holds. Sacks are a team stat.', 'disciplined'], ['We’ll take them when they come. No chasing numbers.', 'patient']),
  Q('ferocious', 'Does a defense need an edge rusher to win?', ['It needs a monster the other quarterback dreams about. Yes.', 'ferocious'], ['It needs eleven monsters who tackle.', 'aggressive'], ['It needs to take the ball away. However it gets done.', 'instinctive']),
  Q('ferocious', 'What makes {star} so disruptive?', ['He wants the quarterback more than the quarterback wants the ball.', 'ferocious', { star: true }], ['Get-off. He’s moving before the ball is.', 'explosive'], ['Technique. He wins with his hands.', 'technical']),
  Q('ferocious', 'Will you blitz {opp}’s young line?', ['We won’t need to. Four of ours against five of theirs is unfair already.', 'ferocious'], ['Some. Enough to keep them guessing.', 'balanced'], ['Only when the down and distance says so.', 'cerebral']),
  Q('ferocious', 'How do you coach pass rush?', ['Hunger first. Technique second. A hungry rusher finds a way.', 'ferocious'], ['Hands and feet. It’s a craft.', 'technical'], ['Effort. The second and third move win more than the first.', 'relentless']),
  Q('ferocious', 'Your defense was quiet last week. What changed?', ['We let them block us. That won’t happen again. We attack.', 'ferocious'], ['They had a good plan. We’ve adjusted.', 'adaptive'], ['Nothing changed. One week. Same defense.', 'hardy']),
  Q('ferocious', 'Do you worry about your rushers getting too far upfield?', ['No. I worry about them not getting there at all.', 'ferocious'], ['Yes. Lane discipline matters against a scrambler.', 'disciplined'], ['A little. We coach it; we don’t coach it out of them.', 'balanced']),
  Q('ferocious', 'What does {opp}’s offensive line do well?', ['Not enough. Ask me again Sunday night.', 'ferocious'], ['They communicate well. We’ll need stunts to beat that.', 'technical'], ['They’re big. We’ll need to be smart.', 'cerebral']),
  Q('ferocious', 'Describe your defense in one word.', ['Predators.', 'ferocious'], ['Disciplined.', 'disciplined'], ['Relentless.', 'relentless']),

  // ---------------------------------------------------------------- protective (blocking)
  Q('protective', 'Your quarterback has barely been touched this season. How?', ['Five monsters who take it personally when someone gets near him.', 'protective'], ['Quick decisions. The ball is gone before the rush arrives.', 'precise'], ['A moving pocket. Hard to hit what moves.', 'elusive']),
  Q('protective', 'How do you handle {opp}’s pass rush?', ['Double the best one, chip the second, and keep the pocket clean all day.', 'protective'], ['Run at them. Tired rushers don’t rush.', 'powerful'], ['Screens. Make the rush work against them.', 'elusive']),
  Q('protective', 'Your running game starts with the line. Agree?', ['Every yard begins with a block. The backs know who to thank.', 'protective'], ['The back makes the line look good as often as the reverse.', 'elusive'], ['It starts with the quarterback reading the box.', 'cerebral']),
  Q('protective', 'Any changes to the offensive line this week?', ['No. These five protect each other as much as the quarterback.', 'protective'], ['One. We want more athleticism on the edge.', 'swift'], ['We’ll see how they handle {opp} first.', 'adaptive']),
  Q('protective', 'What’s the tight end’s job in this offense?', ['Block first. If he does that, the catches come free.', 'protective'], ['Catch everything. He’s a receiver who happens to block.', 'surehanded'], ['Whatever the defense gives up. He’s a chess piece.', 'adaptive']),
  Q('protective', 'How do you keep a rookie quarterback confident?', ['Keep him clean. Confidence is a jersey without grass stains.', 'protective'], ['Easy throws early. Let him see the ball move.', 'precise'], ['Let him play through mistakes. Pulling him teaches nothing.', 'patient']),
  Q('protective', 'Why does {star} never seem to get beaten?', ['He stays on his block until the whistle. No rusher gets a second chance.', 'protective', { star: true }], ['Footwork. He’s never off balance.', 'technical'], ['Strength. Nobody moves him.', 'powerful']),
  Q('protective', 'How important is the offensive line to your identity?', ['It is the identity. Everything else is decoration.', 'protective'], ['Important. But speed is what scares people.', 'swift'], ['As important as every other group. Eleven monsters.', 'balanced']),
  Q('protective', 'Your defense protects leads well. What’s the key?', ['Keep everything in front of you. No big plays, no panic.', 'protective'], ['Keep attacking. Prevent defense prevents wins.', 'aggressive'], ['Take the ball. A turnover ends it.', 'instinctive']),
  Q('protective', 'What did you tell the line after last week’s sacks?', ['That the quarterback is theirs to protect, and they let him down. They heard it.', 'protective'], ['That it was technique, not effort. Fixable.', 'technical'], ['Nothing. They knew. Sometimes silence coaches best.', 'calm']),

  // ---------------------------------------------------------------- slippery (escapes)
  Q('slippery', 'Your backs are almost impossible to tackle one-on-one. Why?', ['They don’t stay where the tackler thinks they are. Slippery by nature.', 'slippery'], ['They’re strong. Arm tackles bounce off.', 'sturdy'], ['They see the tackler early and pick the angle.', 'instinctive']),
  Q('slippery', 'Will we see trick plays against {opp}?', ['You never know with us. That’s the point.', 'slippery'], ['We win with execution, not tricks.', 'precise'], ['One or two. Keep them honest.', 'balanced']),
  Q('slippery', 'Your quarterback escaped three sacks last week. Luck?', ['No. He feels the rush and slides away. Does it every day in practice.', 'slippery'], ['The line recovered well. Team effort.', 'protective'], ['Partly. Sometimes you need a little luck.', 'calm']),
  Q('slippery', 'How do you beat a defense that reads you well?', ['Show them what they expect and do the opposite.', 'slippery'], ['Execute anyway. Knowing isn’t stopping.', 'powerful'], ['Change the tempo. Reads need time.', 'swift']),
  Q('slippery', 'Why is {star} so hard to tackle in the open field?', ['He’s a ghost. Defenders grab air and wonder what happened.', 'slippery', { star: true }], ['Speed. He’s gone before the angle closes.', 'swift'], ['Strength. He runs through arm tackles.', 'powerful']),
  Q('slippery', 'What’s the plan on third and long?', ['Something they haven’t seen. We keep a few in the drawer for that.', 'slippery'], ['Protect and throw past the sticks. Simple.', 'protective'], ['Screen or draw. Let them rush themselves out of it.', 'elusive']),
  Q('slippery', 'Do you ever bluff a play call?', ['Every week. Half the fun is watching them react to nothing.', 'slippery'], ['No. We line up and run our stuff.', 'hardy'], ['Only when the tape says they’re watching.', 'cerebral']),
  Q('slippery', 'Your return game is unpredictable. By design?', ['Yes. If they don’t know where the return is going, neither do their lanes.', 'slippery'], ['By speed. The returner just outruns the plan.', 'swift'], ['By effort. Ten monsters blocking hard open anything.', 'relentless']),
  Q('slippery', 'Any surprises in the lineup Sunday?', ['Maybe. You’ll find out when {opp} does.', 'slippery'], ['No. Same monsters, same jobs.', 'hardy'], ['One small one. A matchup we like.', 'cerebral']),
  Q('slippery', 'How do you keep {opp}’s defense guessing?', ['Same formation, five different plays. Let them pick.', 'slippery'], ['Tempo. They can’t guess if they can’t breathe.', 'swift'], ['We don’t. We execute and let them guess right for all we care.', 'focused']),

  // ---------------------------------------------------------------- secure (ball security)
  Q('secure', 'Your team hasn’t lost a fumble all season. Why?', ['Ball high and tight, every carry, every catch. The yards after are a bonus.', 'secure'], ['Durable monsters. They don’t get knocked off the ball.', 'sturdy'], ['Awareness. They know where the hit is coming from.', 'instinctive']),
  Q('secure', 'The weather looks bad Sunday. Game plan?', ['Hold onto the ball. The team that doesn’t turn it over wins in the rain.', 'secure'], ['Run it. Keep it simple and physical.', 'powerful'], ['Same plan. Weather is the same for both teams.', 'hardy']),
  Q('secure', 'Will the punt returner be more aggressive this week?', ['No. Catch it clean. Possession is worth more than ten yards.', 'secure'], ['Yes. We need the field position.', 'swift'], ['Depends on the coverage. He has the green light if it’s there.', 'instinctive']),
  Q('secure', 'Your offense takes few risks. Is that a weakness?', ['It’s why we’re {record}. Possession wins.', 'secure'], ['Maybe. We may open it up this week.', 'explosive'], ['It’s a choice. The risks come when they’re worth it.', 'cerebral']),
  Q('secure', 'Why does {star} never seem to cough it up?', ['Two hands in traffic, every time. He treats the ball like it’s his.', 'secure', { star: true }], ['Strength. Nobody rips it from him.', 'powerful'], ['Vision. He sees the hit and protects first.', 'instinctive']),
  Q('secure', 'How do you close out a tight game?', ['Keep the ball. Run it, clock it, hand it to the defense with nothing to lose.', 'secure'], ['Keep attacking. Playing not to lose is how you lose.', 'relentless'], ['Trust the defense. Punt and let them finish.', 'disciplined']),
  Q('secure', 'What’s the first rule in your offense?', ['Don’t give it away. Everything else is second.', 'secure'], ['Protect the quarterback.', 'protective'], ['Take what the defense gives you.', 'patient']),
  Q('secure', 'Your quarterback throws it away a lot. Too cautious?', ['No. A throwaway is a win. An interception is a loss. Simple arithmetic.', 'secure'], ['A bit. We want him to trust his arm more.', 'gifted'], ['He makes the right read. Sometimes the read is nobody.', 'precise']),
  Q('secure', 'How do you handle a defense that strips the ball?', ['Two hands, chin down, and we practise it with monsters punching at the ball all week.', 'secure'], ['Avoid the pile. Space is safe.', 'elusive'], ['Hit them first. Strippers get stripped.', 'aggressive']),
  Q('secure', 'Any message to the fans before Sunday?', ['It won’t always be pretty, but we’ll hold on to the ball and we’ll hold on to the win.', 'secure'], ['Get loud. We feed off it.', 'aggressive'], ['Enjoy it. We will.', 'calm']),

  // ---------------------------------------------------------------- gifted (raw talent, abilities)
  Q('gifted', 'Is {star} the best player in this league?', ['Yes. Nobody can do what he does. Nobody.', 'gifted', { star: true }], ['He’s great because the whole team is.', 'balanced'], ['Ask me again after the playoffs.', 'patient']),
  Q('gifted', 'Your monsters’ abilities seem to hit harder than anyone’s. Why?', ['Talent. We recruit gifted monsters and let them be gifted.', 'gifted'], ['Timing. We call them when the moment is right.', 'cerebral'], ['Practice. Even gifts need reps.', 'technical']),
  Q('gifted', 'How much of the game plan is built around {star}?', ['All of it, when it matters. You don’t hide a monster like that.', 'gifted', { star: true }], ['Enough. The other ten count too.', 'balanced'], ['Depends on how they defend him. We go where they aren’t.', 'adaptive']),
  Q('gifted', 'Do you prefer talent or work ethic?', ['Talent. Work ethic doesn’t run a 4.3.', 'gifted'], ['Work. Talent gets you drafted; work keeps you here.', 'relentless'], ['Both, or neither. The great ones have both.', 'balanced']),
  Q('gifted', 'Your rookie made a play nobody expected last week. Surprised?', ['Not at all. That’s why we drafted him. Special monsters do special things.', 'gifted'], ['A little. He’s ahead of schedule.', 'patient'], ['No. He studies. The play was earned.', 'cerebral']),
  Q('gifted', 'How do you coach a monster more talented than any you’ve had?', ['You give him the ball and you don’t over-coach the gift.', 'gifted'], ['Same as the others. Standards don’t bend.', 'disciplined'], ['You challenge him. Talent gets bored.', 'relentless']),
  Q('gifted', 'What will decide Sunday’s game?', ['Our best monsters making plays that theirs can’t.', 'gifted'], ['Turnovers. It always is.', 'secure'], ['The line of scrimmage. Always has.', 'powerful']),
  Q('gifted', 'Will we see the signature ability early?', ['When the moment’s right. And the moment will be loud.', 'gifted'], ['Only when the matchup says so.', 'cerebral'], ['Maybe. We don’t script it.', 'instinctive']),
  Q('gifted', 'How do you keep a star monster hungry?', ['Remind him there’s a level above the one he’s at. There always is.', 'gifted'], ['Competition. Nobody’s spot is safe.', 'relentless'], ['You don’t have to. The good ones stay hungry.', 'hardy']),
  Q('gifted', 'Any trade rumours around {star} you want to address?', ['You don’t trade a monster like that. Next question.', 'gifted', { star: true }], ['We don’t comment on rumours.', 'calm'], ['He’s under contract and he’s happy. That’s all.', 'secure']),

  // ---------------------------------------------------------------- resistant (shrugs off abilities)
  Q('resistant', '{opp} has the most dangerous abilities in the league. Worried?', ['No. Our monsters shrug that stuff off. We play through it.', 'resistant'], ['Respectful. We’ve prepared for every one of them.', 'cerebral'], ['We have our own. Let’s see whose hit harder.', 'gifted']),
  Q('resistant', 'How do you prepare for a monster with a signature ability?', ['You don’t fear it. Line up, absorb it, and move on to the next snap.', 'resistant'], ['Study it. Every ability has a tell.', 'cerebral'], ['Hit the monster before he uses it.', 'ferocious']),
  Q('resistant', 'Your defense has been hard to rattle. Why?', ['Thick skin. Nothing {opp} does is going to change how we line up.', 'resistant'], ['Calm leadership. Nobody panics.', 'calm'], ['Preparation. Nothing surprises us.', 'focused']),
  Q('resistant', 'How do you handle {opp}’s star this week?', ['The same way we handle everyone. He gets no special treatment, and no special effect.', 'resistant'], ['Double him. Make someone else beat us.', 'disciplined'], ['Hit him early. Stars don’t like contact.', 'aggressive']),
  Q('resistant', 'Why does {star} seem immune to the other team’s tricks?', ['He doesn’t react to what they want him to react to. Solid as a wall.', 'resistant', { star: true }], ['He’s seen it all. Nothing is new to him.', 'cerebral'], ['Focus. He only sees his job.', 'focused']),
  Q('resistant', 'Your team seems unbothered by the noise around this game. True?', ['True. Noise bounces off this group.', 'resistant'], ['We like the noise. It means it matters.', 'aggressive'], ['We don’t hear it. Heads down, work.', 'focused']),
  Q('resistant', 'What makes a monster hard to game-plan against?', ['One who can’t be knocked off his game. You can’t scheme a wall.', 'resistant'], ['One who can do three things well.', 'adaptive'], ['One who’s faster than your plan.', 'swift']),
  Q('resistant', 'Does the hype around {opp}’s offense get to your monsters?', ['Hype doesn’t block or tackle. We’re fine.', 'resistant'], ['A little. We use it.', 'aggressive'], ['No. We respect them. That’s different from fear.', 'calm']),
  Q('resistant', 'How do you keep the team steady through a losing streak?', ['Same as a winning one. The outside doesn’t get in.', 'resistant'], ['Fix the three plays that mattered and move on.', 'cerebral'], ['Keep working. The streak breaks when the work shows.', 'relentless']),
  Q('resistant', 'Any concerns about facing {opp}’s legendary monster?', ['A legend is just a monster with a bigger reputation. We play the monster.', 'resistant'], ['Concern, yes. Fear, no. We have a plan.', 'cerebral'], ['We’ll test him early and see how he likes contact.', 'ferocious']),

  // ---------------------------------------------------------------- adaptive (adjusts)
  Q('adaptive', 'Your halftime adjustments have won games. What’s the method?', ['Find what they changed and change faster. The first half is reconnaissance.', 'adaptive'], ['Trust the plan. Usually it was right and we weren’t executing.', 'disciplined'], ['Ask the monsters. They see things from the field I don’t.', 'cerebral']),
  Q('adaptive', 'How do you prepare for a team that changes identity week to week?', ['Prepare three plans and pick one after the first drive.', 'adaptive'], ['Prepare for ourselves. Our game, our way.', 'hardy'], ['Study the coach. Rosters change; tendencies don’t.', 'cerebral']),
  Q('adaptive', '{opp} just changed coordinators. Does that help or hurt you?', ['It hurts for one quarter. Then we adjust and it helps.', 'adaptive'], ['Neither. We play our game.', 'hardy'], ['It helps. New coordinators show their whole hand early.', 'cerebral']),
  Q('adaptive', 'Why does {star} fit every scheme you’ve run?', ['He adjusts. Change the play, change the position, he just nods and goes.', 'adaptive', { star: true }], ['Talent fits everywhere.', 'gifted'], ['He studies. He knows every job on the field.', 'cerebral']),
  Q('adaptive', 'Your play calling changed dramatically after the first quarter last week. Why?', ['Because the first quarter told us what to call. We listened.', 'adaptive'], ['Because the first plan was wrong. I’ll own that.', 'calm'], ['Because they showed a look the tape didn’t. We had the answer ready.', 'cerebral']),
  Q('adaptive', 'If {opp} takes away the run, what then?', ['Then we throw. If they take that away, we run. We’re comfortable either way.', 'adaptive'], ['Then we run harder. Nobody takes away what we do.', 'powerful'], ['Then we take the short stuff and wait.', 'patient']),
  Q('adaptive', 'How do you handle in-game injuries?', ['Next monster, new plan. We have a package for every version of this roster.', 'adaptive'], ['Next monster up. Our depth is ready.', 'hardy'], ['Carefully. Nobody plays hurt.', 'calm']),
  Q('adaptive', 'Do you have a base defense?', ['We have five. The offense picks which one it sees.', 'adaptive'], ['Yes, and we run it until someone makes us change.', 'hardy'], ['Attack. That’s the base.', 'ferocious']),
  Q('adaptive', 'What did you change after the loss to {opp}?', ['Plenty. A loss is information. We used all of it.', 'adaptive'], ['Nothing. One game. Same team.', 'hardy'], ['The details. The big picture was fine.', 'technical']),
  Q('adaptive', 'How do you game-plan a team you beat already this season?', ['Assume they’ve changed and plan to change with them.', 'adaptive'], ['Same plan. It worked.', 'hardy'], ['Study what they fixed. The tape will show it.', 'cerebral']),

  // ---------------------------------------------------------------- patient (waits)
  Q('patient', 'Your offense takes a while to get going. Concern?', ['No. We take what they give us until they give us the game.', 'patient'], ['Yes. We’re working on faster starts.', 'explosive'], ['It’s the plan. Wear them down.', 'relentless']),
  Q('patient', 'When do you take the deep shot?', ['When they’ve forgotten we can. Not before.', 'patient'], ['Every chance we get.', 'explosive'], ['When the coverage tells us to.', 'cerebral']),
  Q('patient', 'Your linemen seem to wait for the defender to commit. Why?', ['Let him pick wrong, then finish him. Patience is a blocking technique.', 'patient'], ['Technique. Hands and feet.', 'technical'], ['Strength. Whatever he picks, he loses.', 'powerful']),
  Q('patient', 'Your rookies aren’t playing much. Why?', ['They’ll play when they’re ready. Rushing a monster ruins him.', 'patient'], ['The veterans are better. Simple.', 'hardy'], ['Soon. One or two are close.', 'adaptive']),
  Q('patient', 'What makes {star} such a smooth runner?', ['He waits. The hole opens a half-second later than you expect, and he’s there.', 'patient', { star: true }], ['Vision. He sees it before it opens.', 'instinctive'], ['Feet. He changes direction without slowing down.', 'elusive']),
  Q('patient', 'Fourth and two at midfield, tied, early. Go?', ['Punt. The game is long and the field position is ours.', 'patient'], ['Go. Set the tone.', 'aggressive'], ['Whatever the numbers say.', 'cerebral']),
  Q('patient', 'How do you coach a quarterback who forces throws?', ['Teach him the checkdown is a win. The big play is a reward for waiting.', 'patient'], ['Simplify. Fewer reads, fewer forced balls.', 'disciplined'], ['Show him the tape. He’ll see it.', 'cerebral']),
  Q('patient', 'Is a slow start acceptable against {opp}?', ['If the finish is right, yes. Games are won late.', 'patient'], ['No. We need to come out swinging.', 'explosive'], ['Nothing is acceptable but a win. How we get there is detail.', 'focused']),
  Q('patient', 'Your defense gives up short completions. By design?', ['By design. Let them nibble. Nobody drives ninety yards with twelve passes without a mistake.', 'patient'], ['No. We’re fixing it.', 'aggressive'], ['Partly. We take away the deep ball first.', 'disciplined']),
  Q('patient', 'How do you build a program?', ['Slowly. Scout right, sign right, develop, wait. Shortcuts cost you later.', 'patient'], ['Talent. Sign the best monsters and go.', 'gifted'], ['Culture. Standards first, wins follow.', 'disciplined']),

  // ---------------------------------------------------------------- balanced (neutral)
  Q('balanced', 'What’s the identity of this team?', ['Balance. Run, pass, defend. No weakness to attack.', 'balanced'], ['Toughness. We outlast people.', 'sturdy'], ['Speed. We outrun people.', 'swift']),
  Q('balanced', 'Run or pass this week?', ['Both, in equal measure. Make them defend the whole field.', 'balanced'], ['Run. Until they stop it.', 'powerful'], ['Pass. Their secondary can’t cover.', 'precise']),
  Q('balanced', 'Where’s the weakness on this roster?', ['Nowhere specific. We built it so no single group has to carry the load.', 'balanced'], ['Depth. One injury and it shows.', 'hardy'], ['Youth. We’ll be better in December.', 'patient']),
  Q('balanced', 'Who’s your most important monster?', ['The one with the ball on that snap. We don’t do stars here.', 'balanced'], ['{star}. Obviously.', 'gifted', { star: true }], ['The one who makes the fewest mistakes.', 'focused']),
  Q('balanced', 'How do you divide the carries?', ['Evenly. Fresh backs late and nobody for the defense to key on.', 'balanced'], ['Hot hand. Whoever is running well keeps running.', 'instinctive'], ['The starter gets most. He’s earned them.', 'hardy']),
  Q('balanced', 'What do you tell a team that’s {record}?', ['Keep doing a little of everything well. That’s how you got here.', 'balanced'], ['Keep stacking good days. Nothing changes.', 'hardy'], ['Not good enough. I want more.', 'aggressive']),
  Q('balanced', 'How do you game-plan {opp}?', ['Even. We don’t load up on one thing; they adjust to that too fast.', 'balanced'], ['Attack their weakness until it bleeds.', 'ferocious'], ['Take what they give us.', 'patient']),
  Q('balanced', 'Will the offense lean on {star} more this week?', ['No more than anyone else. Ten monsters catching the ball is harder to stop than one.', 'balanced'], ['Yes. Feed the beast.', 'gifted', { star: true }], ['Depends on the coverage.', 'adaptive']),
  Q('balanced', 'What’s more important, offense or defense?', ['Neither. The team that does both at seventy percent beats the team that does one at ninety.', 'balanced'], ['Defense. It travels.', 'disciplined'], ['Offense. Points win.', 'explosive']),
  Q('balanced', 'What are you working on this week?', ['A bit of everything. No glaring weakness, no glaring strength. Just better.', 'balanced'], ['Details. Footwork, reads, assignments.', 'technical'], ['Finishing. Fourth quarters.', 'relentless']),

  // ---------------------------------------------------------------- calm (unflappable)
  Q('calm', 'Big game Sunday. How’s the mood?', ['Quiet. Same as any week. Loud teams lose big games.', 'calm'], ['Fired up. You can feel it in the building.', 'aggressive'], ['Focused. Nobody is talking about anything but their job.', 'focused']),
  Q('calm', 'How do you handle a two-minute drill?', ['Breathe. The clock is a tool, not a threat. We’ve done it a hundred times.', 'calm'], ['Tempo. Go, go, go.', 'swift'], ['Precision. Every throw to the sideline, every spot exact.', 'precise']),
  Q('calm', 'Your team came back from fourteen down last week. What was said at halftime?', ['Nothing dramatic. Run the offense. Panic loses games faster than deficits.', 'calm'], ['A lot. Some of it unprintable.', 'ferocious'], ['The adjustments. We found what was there and took it.', 'adaptive']),
  Q('calm', 'Does the rivalry with {rival} get under your skin?', ['No. It gets under theirs. That’s enough.', 'calm'], ['Yes, and I like it that way.', 'aggressive'], ['It’s a game on the schedule. A big one. That’s all.', 'hardy']),
  Q('calm', 'Why is {star} so good in the clutch?', ['Nothing speeds up for him. Fourth quarter, first quarter, same heartbeat.', 'calm', { star: true }], ['Talent. The great ones want the ball late.', 'gifted'], ['Preparation. He’s seen the moment before it comes.', 'cerebral']),
  Q('calm', 'Any response to {opp}’s coach’s comments this week?', ['No. We’ll talk Sunday, on the scoreboard, quietly.', 'calm'], ['He should be worried. We’re coming.', 'ferocious'], ['He’s entitled to his opinion. We have ours.', 'hardy']),
  Q('calm', 'How do you handle a bad call?', ['Next play. Officials are weather. You don’t argue with weather.', 'calm'], ['I let them know. Politely. Mostly.', 'aggressive'], ['Note it, move on, discuss it Monday.', 'disciplined']),
  Q('calm', 'How do you keep the sideline composed when things go wrong?', ['By being composed. They watch me. If I’m steady, they’re steady.', 'calm'], ['By fixing it. Composure comes from answers.', 'adaptive'], ['Veterans. They’ve seen worse.', 'hardy']),
  Q('calm', 'What’s your message to the fans before a game like this?', ['Enjoy it. We will. It’s a game, and a good one.', 'calm'], ['Get loud. Make it hurt to visit.', 'aggressive'], ['Stay till the end. We finish.', 'relentless']),
  Q('calm', 'Your team has trailed in every game and won most. How?', ['Nobody blinks. Deficits are information, not emergencies.', 'calm'], ['We don’t quit. Ever.', 'relentless'], ['Halftime. We adjust better than anyone.', 'adaptive']),

  // ---------------------------------------------------------------- hardy (steady week to week)
  Q('hardy', 'Your team is {record}. What’s the message in the locker room?', ['Keep stacking good days. Nothing changes.', 'hardy'], ['Not good enough. I want more.', 'aggressive'], ['Trust the plan. Results follow.', 'focused']),
  Q('hardy', 'Any changes after last week?', ['No. One week is one week. Same routine, same monsters, same standards.', 'hardy'], ['A few. A loss is information.', 'adaptive'], ['Details only. The big picture was fine.', 'technical']),
  Q('hardy', 'How do you handle the long season?', ['One week at a time, every week the same. Consistency is a skill.', 'hardy'], ['Rotate, rest, recover. Depth is a strategy.', 'sturdy'], ['Peak late. Everything builds to December.', 'patient']),
  Q('hardy', 'What makes {star} so reliable?', ['He shows up. Every week, same level. You could set a clock by him.', 'hardy', { star: true }], ['He locks in. Nothing outside the lines reaches him.', 'focused'], ['Talent. It doesn’t have off weeks.', 'gifted']),
  Q('hardy', 'Your depth was tested last week. Verdict?', ['Passed. Next monster up isn’t a slogan here; it’s a roster plan.', 'hardy'], ['Mixed. We found a couple of holes to fill.', 'adaptive'], ['Passed. The backups are starters who haven’t started yet.', 'sturdy']),
  Q('hardy', 'Do you change the routine for a rival game?', ['Never. The routine is why we win rival games.', 'hardy'], ['A little more edge. The monsters feel it.', 'aggressive'], ['Only the walk-through. More situational work.', 'cerebral']),
  Q('hardy', 'How do you keep the standard when you’re winning?', ['Same practice, same film, same corrections. Winning is not a reason to relax.', 'hardy'], ['Remind them who’s next. {opp} doesn’t care about last week.', 'focused'], ['Competition. Nobody’s spot is safe.', 'relentless']),
  Q('hardy', 'Who’s the heart of this team?', ['The monsters you never read about. They show up every week and do the job.', 'hardy'], ['{star}. Everyone follows him.', 'gifted', { star: true }], ['The line. Everything starts there.', 'protective']),
  Q('hardy', 'How do you prepare for the playoffs while still playing out the season?', ['You don’t. You prepare for Sunday. The playoffs are a Sunday too.', 'hardy'], ['Rest the starters a little. Health matters more than seeding.', 'sturdy'], ['Save a few plays. December needs surprises.', 'slippery']),
  Q('hardy', 'Any superstitions?', ['Same routine every week. Call it superstition; I call it preparation.', 'hardy'], ['None. Preparation is my superstition.', 'cerebral'], ['A few. I’m not telling you which.', 'slippery']),

  // ---------------------------------------------------------------- situational questions (counted above the 250)
  Q('aggressive', 'Any words for {rival} and their GM?', ['They should be worried. We’re coming.', 'aggressive', { hype: true }], ['Respect. It’s a big game for both clubs.', 'calm'], ['It’s just another game on the schedule.', 'hardy'], { rival: true }),
  Q('calm', 'The board has been quiet about your future. Are you worried about your job?', ['No. I worry about Sunday. The job takes care of itself when Sunday does.', 'calm'], ['Worried? We’re going to win and then we’ll talk.', 'aggressive'], ['I don’t read the papers. Ask the monsters if they believe. They do.', 'resistant'], { hotseat: true }),
  Q('focused', 'Win or go home. How do you prepare for a playoff game?', ['Same as any week. The monsters who treat it like a normal Sunday are the ones who play well.', 'focused'], ['With everything we’ve got. Nothing saved, nothing held back.', 'relentless'], ['Enjoy it. These are the games you play for.', 'calm'], { playoff: true }),
  Q('hardy', 'Three straight wins. Is this team peaking?', ['Peaking is for teams that stop. We’re just working.', 'hardy'], ['We’re getting better. Not peaking yet.', 'patient'], ['Ask me after Sunday. Streaks mean nothing until they’re over.', 'calm'], { streakW: true }),
  Q('resistant', 'Three straight losses. Is the locker room still with you?', ['Completely. This group doesn’t crack. Watch Sunday.', 'resistant'], ['Yes. We watched the tape together and fixed what we saw.', 'cerebral'], ['Yes. Losing streaks end when the work shows. The work is there.', 'relentless'], { streakL: true }),
  Q('hardy', 'How does the lineup change with your starter out?', ['It doesn’t change much. Next monster up — that’s why we carry depth.', 'hardy'], ['We adjust the plan around who we have. Different, not worse.', 'adaptive'], ['The line protects whoever is back there a little harder.', 'protective'], { injury: true }),
]);

export const MEDIA_BOOST = 3; // to the matching nature's strength (awareness for neutral natures); +1 awareness alongside
export const MEDIA_CAP = 4;   // the same nature twice in one presser does not stack past this
export const HYPE_BOOST = 2;  // trash talk before a rival game: the whole team... and a cost if you lose
export const MEDIA_QUESTIONS_PER_WEEK = 3;

/** Every nature at least ten questions, every answer a known nature — checked by the tests. */
export const questionCount = (nature) => QUESTIONS.filter((q) => q.nature === nature && !isSituational(q)).length;
export const isSituational = (q) => !!(q.rival || q.hotseat || q.playoff || q.streakW || q.streakL || q.injury);
